# Created by OpenAI
"""Shared MoE arithmetic, tile-layout, asynchronous-copy, and reduction primitives."""
from triton.experimental import gluon
from triton.experimental.gluon import language as gl

@gluon.jit
def _sigmoid(x):
    return 1.0 / (1.0 + gl.exp(-x))

@gluon.jit
def _weight_offset(n, k, K: gl.constexpr):
    return n // 16 * K * 16 + k // 16 * 256 + n % 16 * 16 + k % 16

@gluon.jit
def _sum(a, b):
    return a + b

@gluon.constexpr_function
def _weight_shared_layout(rows):
    return gl.SharedLinearLayout([[0, 1 << i] for i in range(4)] + [[1 << i, 0] for i in range(4)] + [[0, 1 << i] for i in range(4, 7)] + [[1 << i, 0] for i in range(4, rows.bit_length() - 1)])

# Created by OpenAI
from ._common import _sigmoid, _weight_offset, _weight_shared_layout
from typing import NamedTuple
from triton.experimental import gluon
from triton.experimental.gluon import language as gl
from triton.experimental.gluon.language.amd import cdna4

class _Policy(NamedTuple):
    router_rows: int
    router_prefetch: int
    router_hidden_prefetch: int
    router_k: int
    expert_rows: int
    up_columns: int
    up_matrix_m: int
    shared_up_columns: int
    up_stripes: int
    down_columns: int
    finish_rows: int
    finish_columns: int
    finish_prefetch: int

@gluon.jit
def _quantize(x):
    gl.static_assert(x.shape[1] == 128)
    x = x.to(gl.float32)
    scale = gl.div_rn(gl.maximum(gl.max(gl.abs(x), 1), 1e-10), 448.0)
    return ((x * gl.div_rn(1.0, scale)[:, None]).to(gl.float8e4nv), scale)

@gluon.constexpr_function
def _mma_layout(waves, matrix_m=16, native=False):
    if matrix_m == 32:
        shape = [32, 32, 64] if native else [32, 32, 16]
    else:
        shape = [16, 16, 128] if native else [16, 16, 32]
    return gl.amd.AMDMFMALayout(version=4, instr_shape=shape, warps_per_cta=[1, waves], transposed=True)

@gluon.constexpr_function
def _dot_width(mma):
    return 32 if mma.instr_shape[2] == 128 else 16

@gluon.constexpr_function
def _activation_layout():
    return gl.BlockedLayout([1, 16], [8, 8], [4, 1], [1, 0])

@gluon.constexpr_function
def _weight_layout(matrix_m=16):
    return gl.BlockedLayout([1, 16], [matrix_m, 64 // matrix_m], [4, 1], [0, 1])

@gluon.constexpr_function
def _output_layout():
    return gl.BlockedLayout([1, 8], [4, 16], [4, 1], [1, 0])

@gluon.jit
def _scaled_group(a, b, sa, sb, acc, NATIVE: gl.constexpr):
    mma: gl.constexpr = acc.type.layout
    a = gl.convert_layout(a, gl.DotOperandLayout(0, mma, _dot_width(mma)))
    b = gl.convert_layout(b, gl.DotOperandLayout(1, mma, _dot_width(mma)))
    zero = gl.full((a.shape[0], b.shape[1]), 0, gl.float32, mma)
    if NATIVE:
        partial = cdna4.mfma_scaled(a, None, 'e4m3', b, None, 'e4m3', zero)
    else:
        a, b = (a.to(gl.bfloat16), b.to(gl.bfloat16))
        partial = cdna4.mfma(a, b, zero)
    return acc + partial * sa[:, None] * sb[None, :]

@gluon.jit
def _quantize_hidden(X, Q, S, M: gl.constexpr, H: gl.constexpr, tile, group):
    ld: gl.constexpr = gl.BlockedLayout([1, 8], [4, 16], [1, 1], [1, 0])
    r = tile * 16 + gl.arange(0, 16, layout=gl.SliceLayout(1, ld))
    k = group * 128 + gl.arange(0, 128, layout=gl.SliceLayout(0, ld))
    q, s = _quantize(gl.load(X + r[:, None] * H + k[None, :], r[:, None] < M, 0))
    gl.store(Q + r[:, None] * H + k[None, :], q, r[:, None] < M)
    gl.store(S + r * (H // 128) + group, s, r < M)

@gluon.jit
def _router_tile(X, W, Y, M: gl.constexpr, H: gl.constexpr, E: gl.constexpr, cfg: gl.constexpr, pidm, pidn):
    BM: gl.constexpr = cfg.router_rows
    BK: gl.constexpr = cfg.router_k
    AP: gl.constexpr = cfg.router_hidden_prefetch
    WP: gl.constexpr = cfg.router_prefetch
    gl.static_assert(H % (BK * WP) == 0 and WP % AP == 0)
    ld: gl.constexpr = gl.BlockedLayout([1, 8], [4, 16], [1, 1], [1, 0])
    mma: gl.constexpr = _mma_layout(1)
    r = pidm * BM + gl.arange(0, BM, gl.SliceLayout(1, ld))
    n = pidn * 16 + gl.arange(0, 16, gl.SliceLayout(1, ld))
    k = gl.arange(0, BK, gl.SliceLayout(0, ld))
    ao, bo = (r[:, None] * H + k[None, :], n[:, None] * H + k[None, :])
    aa, bb = ((), ())
    for slot in gl.static_range(AP):
        aa += (gl.load(X + ao + slot * BK, r[:, None] < M, 0),)
    for slot in gl.static_range(WP):
        bb += (gl.load(W + bo + slot * BK, n[:, None] < E, 0),)
    acc = gl.full((BM, 16), 0, gl.float32, mma)
    for chunk in range(H // (BK * WP)):
        for slot in gl.static_range(WP):
            a, b = (aa[slot % AP], bb[slot])
            a = gl.convert_layout(a, gl.DotOperandLayout(0, mma, 8))
            b = gl.convert_layout(b.trans(), gl.DotOperandLayout(1, mma, 8))
            step = chunk * WP + slot
            if step + AP < H // BK:
                ahead = gl.load(X + ao + (step + AP) * BK, r[:, None] < M, 0)
                aa = aa[:slot % AP] + (ahead,) + aa[slot % AP + 1:]
            if step + WP < H // BK:
                ahead = gl.load(W + bo + (step + WP) * BK, n[:, None] < E, 0)
                bb = bb[:slot] + (ahead,) + bb[slot + 1:]
            acc = cdna4.mfma(a, b, acc)
    outld: gl.constexpr = gl.BlockedLayout([1, 4], [4, 16], [1, 1], [1, 0])
    rr = pidm * BM + gl.arange(0, BM, gl.SliceLayout(1, outld))
    nn = pidn * 16 + gl.arange(0, 16, gl.SliceLayout(0, outld))
    gl.store(Y + rr[:, None] * E + nn[None, :], gl.convert_layout(acc, outld), (rr[:, None] < M) & (nn[None, :] < E))

@gluon.jit
def _route_tile(Plan, tile, BM: gl.constexpr, R: gl.constexpr, ld: gl.constexpr):
    SHIFT: gl.constexpr = R.bit_length()
    block = Plan + 1 + tile * BM
    routes = gl.load(block + gl.arange(0, BM, ld)) & (1 << SHIFT) - 1
    expert = gl.load(block).to(gl.uint32) >> SHIFT
    return (routes, expert)

@gluon.jit
def _scale_table(values):
    table = gl.allocate_shared_memory(gl.float32, [values.shape[1], values.shape[0]], gl.SwizzledSharedLayout(1, 1, 1, [1, 0]), value=values.trans())
    return table._reinterpret(layout=gl.SwizzledSharedLayout(1, 1, 1, [0]))

@gluon.constexpr_function
def _scale_blocks(groups):
    blocks = []
    first = 0
    while groups:
        size = 1 << groups.bit_length() - 1
        blocks.append((first, size))
        first += size
        groups -= size
    return tuple(blocks)

@gluon.jit
def _issue_up(stage, X, W, aoff, boff, valid, SHARED: gl.constexpr):
    CACHE: gl.constexpr = '.ca' if SHARED else '.cg'
    cdna4.async_copy.buffer_load_to_shared(stage[0], X, aoff, mask=valid, other=0.0)
    cdna4.async_copy.buffer_load_to_shared(stage[1], W, boff, cache_modifier=CACHE)
    cdna4.async_copy.commit_group()

@gluon.jit
def _up_scales(XS, WS, src, valid, expert, panel, H: gl.constexpr, WF: gl.constexpr, BN: gl.constexpr):
    ld: gl.constexpr = gl.BlockedLayout([1, 4], [4, 16], [4, 1], [1, 0])
    rows = gl.convert_layout(src, gl.SliceLayout(1, ld))
    mask = gl.convert_layout(valid, gl.SliceLayout(1, ld))
    pair = gl.arange(0, 2, layout=gl.SliceLayout(1, ld))
    wsg = expert * gl.cdiv(2 * WF, 128) + panel * BN // 128 + pair * (WF // 128)
    BLOCKS: gl.constexpr = _scale_blocks(H // 128)
    tables = ()
    for bank in gl.static_range(len(BLOCKS)):
        group = BLOCKS[bank][0] + gl.arange(0, BLOCKS[bank][1], gl.SliceLayout(0, ld))
        sx = gl.load(XS + rows[:, None] * (H // 128) + group[None, :], mask[:, None], 0.0)
        sw = gl.load(WS + wsg[:, None] * (H // 128) + group[None, :])
        tables += ((_scale_table(sx), _scale_table(sw)),)
    return tables

@gluon.jit
def _up_group(stage, X, W, aoff, boff, valid, scales, local_step, step, acc, SHARED: gl.constexpr, REFILL: gl.constexpr):
    mma: gl.constexpr = acc.type.layout
    BN: gl.constexpr = acc.shape[1] // 2
    cdna4.async_copy.wait_group(0)
    a = cdna4.async_copy.load_shared_relaxed(stage[0], gl.DotOperandLayout(0, mma, _dot_width(mma)))
    b = cdna4.async_copy.load_shared_relaxed(stage[1].permute((1, 0)), gl.DotOperandLayout(1, mma, _dot_width(mma)))
    if REFILL:
        gl.barrier()
        _issue_up(stage, X, W, aoff + (step + 1) * 128, boff + (step + 1) * 128 * 16, valid, SHARED)
    sa = cdna4.async_copy.load_shared_relaxed(scales[0].index(local_step), gl.SliceLayout(1, mma))
    column = gl.arange(0, 2 * BN, gl.SliceLayout(0, mma))
    sb = scales[1].index(local_step).gather(column // BN, 0)
    return _scaled_group(a, b, sa, sb, acc, False)

@gluon.jit
def _up_tile(X, XS, W, WS, Plan, A, tile, pidn, M: gl.constexpr, H: gl.constexpr, F: gl.constexpr, WF: gl.constexpr, TOPK: gl.constexpr, E: gl.constexpr, cfg: gl.constexpr, SHARED: gl.constexpr):
    BM: gl.constexpr = cfg.expert_rows
    BN: gl.constexpr = cfg.shared_up_columns if SHARED else cfg.up_columns
    ald: gl.constexpr = _activation_layout()
    bld: gl.constexpr = _weight_layout()
    mma: gl.constexpr = _mma_layout(4, 16 if SHARED else cfg.up_matrix_m, False)
    rm = gl.arange(0, BM, layout=gl.SliceLayout(1, ald))
    if SHARED:
        src, expert, base = (tile * BM + rm, E, 0)
    else:
        route, expert = _route_tile(Plan, tile, BM, M * TOPK, gl.SliceLayout(1, ald))
        src, base = (route // TOPK, gl.cdiv(M, BM) * BM)
    valid = src < M
    kk = gl.arange(0, 128, layout=gl.SliceLayout(0, ald))
    nn = gl.arange(0, 2 * BN, layout=gl.SliceLayout(1, bld))
    n = pidn * BN + nn % BN + nn // BN * WF
    wk = gl.arange(0, 128, layout=gl.SliceLayout(0, bld))
    boff = _weight_offset(n[:, None], wk[None, :], H)
    aoff = src[:, None] * H + kk[None, :]
    wp = W + gl.cast(expert, gl.int64) * (2 * WF * H)
    stage = (gl.allocate_shared_memory(X.dtype.element_ty, [BM, 128], gl.SwizzledSharedLayout(16, 1, 8, [1, 0])), gl.allocate_shared_memory(W.dtype.element_ty, [2 * BN, 128], _weight_shared_layout(2 * BN)))
    scales = _up_scales(XS, WS, src, valid, expert, pidn, H, WF, BN)
    gl.barrier()
    _issue_up(stage, X, wp, aoff, boff, valid[:, None], SHARED)
    acc = gl.full((BM, 2 * BN), 0, gl.float32, mma)
    BLOCKS: gl.constexpr = _scale_blocks(H // 128)
    for bank in gl.static_range(len(BLOCKS)):
        for local_step in range(BLOCKS[bank][1] - int(bank == len(BLOCKS) - 1)):
            acc = _up_group(stage, X, wp, aoff, boff, valid[:, None], scales[bank], local_step, BLOCKS[bank][0] + local_step, acc, SHARED, True)
    acc = _up_group(stage, X, wp, aoff, boff, valid[:, None], scales[-1], BLOCKS[-1][1] - 1, H // 128 - 1, acc, SHARED, False)
    outld: gl.constexpr = gl.BlockedLayout([1, min(4, BN // 16)], [4, 16], [4, 1], [1, 0])
    rounded = gl.convert_layout(acc.to(gl.bfloat16).to(gl.float32), outld)
    gate, up = gl.split(rounded.reshape((BM, 2, BN)).permute((0, 2, 1)))
    gate, up = (gl.convert_layout(gate, outld), gl.convert_layout(up, outld))
    act = (gate * _sigmoid(gate) * up).to(gl.bfloat16)
    rr = base + tile * BM + gl.arange(0, BM, layout=gl.SliceLayout(1, outld))
    cn = pidn * BN + gl.arange(0, BN, layout=gl.SliceLayout(0, outld))
    gl.store(A + rr[:, None] * F + cn[None, :], act)

@gluon.jit
def _up(X, XS, W, WS, Plan, A, M: gl.constexpr, H: gl.constexpr, F: gl.constexpr, WF: gl.constexpr, TOPK: gl.constexpr, E: gl.constexpr, cfg: gl.constexpr):
    nt: gl.constexpr = F // cfg.up_columns
    BM: gl.constexpr = cfg.expert_rows
    snt: gl.constexpr = F // cfg.shared_up_columns
    shared_jobs: gl.constexpr = gl.cdiv(M, BM) * snt
    job = gl.program_id(0)
    if cfg.up_stripes > 1:
        live_jobs = shared_jobs + gl.cdiv(gl.load(Plan), BM) * nt
        stripe_jobs = gl.cdiv(live_jobs, cfg.up_stripes)
        job = job % cfg.up_stripes * stripe_jobs + job // cfg.up_stripes
        if (gl.program_id(0) // cfg.up_stripes >= stripe_jobs) | (job >= live_jobs):
            return
    if job < shared_jobs:
        _up_tile(X, XS, W, WS, Plan, A, job // snt, job % snt, M, H, F, WF, TOPK, E, cfg, True)
    else:
        tile = (job - shared_jobs) // nt
        if tile * BM < gl.load(Plan):
            _up_tile(X, XS, W, WS, Plan, A, tile, job % nt, M, H, F, WF, TOPK, E, cfg, False)
